param([string]$Source,[string]$TestParent)
$ErrorActionPreference='Stop';. $Source
$installed='C:\ProgramData\CormierDnsManager';$settings=Get-Content -LiteralPath ($installed+'\configuration.json') -Raw|ConvertFrom-Json
$beforeHashes=@{configuration=(Get-FileHash -LiteralPath ($installed+'\configuration.json')).Hash;kubeconfig=(Get-FileHash -LiteralPath $settings.kubeconfig).Hash;bridge=(Get-FileHash -LiteralPath ($installed+'\windows-dns-bridge.ps1')).Hash}
$target=[IO.File]::ReadAllText($settings.kubeconfig);$config=$target|ConvertFrom-Json;$ca=$config.clusters[0].cluster.'certificate-authority-data'
$initial=& $settings.kubectl --kubeconfig $settings.kubeconfig auth whoami -o json 2>$null;if($LASTEXITCODE -ne 0){throw 'Installed bridge identity is unavailable'};$known=($initial|ConvertFrom-Json).status.userInfo;if($known.username -cne 'system:serviceaccount:dns-system:dns-windows-bridge' -or !$known.uid){throw 'Installed bridge identity differs'}
$script:dropReadback=$false;$script:checks=@()
$authenticate={param($path,$expectedUid);$raw=& $settings.kubectl --kubeconfig $path auth whoami -o json 2>$null;if($LASTEXITCODE -ne 0){return $false};$identity=($raw|ConvertFrom-Json).status.userInfo;if($expectedUid -cne $known.uid -or $identity.uid -cne $expectedUid -or $identity.username -cne $known.username -or @(@('system:authenticated','system:serviceaccounts','system:serviceaccounts:dns-system')|Where-Object {$_ -notin $identity.groups}).Count){return $false};foreach($name in @('dns-windows-queue','dns-windows-observations')){$null=& $settings.kubectl --kubeconfig $path -n dns-system get configmap $name -o json 2>$null;if($LASTEXITCODE -ne 0){return $false}};if($script:dropReadback -and [IO.Path]::GetFileName($path) -eq 'kubeconfig.json'){$script:dropReadback=$false;throw 'Injected loss after confirmed installed identity'};return $true}
$idle={$queue=& $settings.kubectl --kubeconfig $settings.kubeconfig -n dns-system get configmap dns-windows-queue -o json 2>$null;if($LASTEXITCODE -ne 0){return $false};$jobs=(($queue|ConvertFrom-Json).data.'jobs.json'|ConvertFrom-Json);return @($jobs|Where-Object {$_.status -in @('Queued','Running')}).Count -eq 0}
function Case([string]$Mode){$id=[Guid]::NewGuid().ToString();$root=Join-Path $TestParent ('case-'+$id);New-Item -ItemType Directory -Path $root|Out-Null;& icacls $root /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F'|Out-Null;if($LASTEXITCODE -ne 0){throw 'Private fixture permissions failed'};if($Mode -eq 'Unchanged'){[IO.File]::WriteAllBytes((Join-Path $root 'kubeconfig.json'),[IO.File]::ReadAllBytes($settings.kubeconfig))}elseif($Mode -eq 'Invalid'){$bad=$target|ConvertFrom-Json;$bad.users[0].user.token='synthetic.invalid.signature';[IO.File]::WriteAllText((Join-Path $root 'kubeconfig.json'),($bad|ConvertTo-Json -Depth 12))};return @{Root=$root;Id=$id;TargetJson=$target;ClusterCaData=$ca;AccountUid=[string]$known.uid;AssertQuiescent=$idle}}
$f=Case 'Unchanged';$file=Join-Path $f.Root 'kubeconfig.json';$timestamp=(Get-Item -LiteralPath $file).LastWriteTimeUtc;$null=New-DnsCredentialRecovery @f;$result=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent $idle;if($result.status -ne 'Applied' -or (Get-Item -LiteralPath $file).LastWriteTimeUtc -ne $timestamp){throw 'Unchanged authenticated fixture was rewritten'};$script:checks+='Actual bridge identity and named ConfigMap access; unchanged bytes and timestamp preserved'
$f=Case 'Missing';$null=New-DnsCredentialRecovery @f;$result=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent $idle;if($result.status -ne 'Applied'){throw 'Missing private kubeconfig not restored'};$script:checks+='Missing private kubeconfig restored and authenticated against installed cluster'
$f=Case 'Invalid';$null=New-DnsCredentialRecovery @f;$script:dropReadback=$true;$interrupted=$false;try{$null=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent $idle}catch{$interrupted=$true};if(!$interrupted){throw 'Readback interruption not retained'};$file=Join-Path $f.Root 'kubeconfig.json';$timestamp=(Get-Item -LiteralPath $file).LastWriteTimeUtc;. $Source;$result=Repair-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate;if($result.status -ne 'Applied' -or (Get-Item -LiteralPath $file).LastWriteTimeUtc -ne $timestamp){throw 'Authenticated reconciliation replayed the private write'};$script:checks+='Invalid private kubeconfig restored; restarted helper reconciles authenticated accepted write without replay'
$f=Case 'Invalid';$f.AccountUid='foreign-account-uid';$null=New-DnsCredentialRecovery @f;$file=Join-Path $f.Root 'kubeconfig.json';$hash=(Get-FileHash -LiteralPath $file).Hash;$rejected=$false;try{$null=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent $idle}catch{$rejected=$true};if(!$rejected -or (Get-FileHash -LiteralPath $file).Hash -ne $hash){throw 'Wrong account identity changed private configuration'};$script:checks+='Foreign account UID rejected before replacing private configuration'
$afterHashes=@{configuration=(Get-FileHash -LiteralPath ($installed+'\configuration.json')).Hash;kubeconfig=(Get-FileHash -LiteralPath $settings.kubeconfig).Hash;bridge=(Get-FileHash -LiteralPath ($installed+'\windows-dns-bridge.ps1')).Hash};foreach($key in $beforeHashes.Keys){if($beforeHashes[$key] -cne $afterHashes[$key]){throw 'Installed bridge file changed'}};if((Get-ScheduledTask -TaskName 'Cormier DNS Manager Bridge').State -ne 'Running'){throw 'Installed bridge is not running'};$script:checks+='Installed configuration, kubeconfig, bridge source and running scheduled task preserved'
@{passed=$true;checks=$script:checks;productionWrites=0;accountUid=[string]$known.uid;installedFileHashes=$afterHashes}|ConvertTo-Json -Depth 10
